    SELECT id INTO v_lesson_id FROM lessons WHERE topic_id=v_topic_id AND title='Common Irregular Verbs in Everyday Events';
    IF v_lesson_id IS NULL THEN INSERT INTO lessons(topic_id,teacher_id,title,description,content,skill_type,order_index,status) VALUES(v_topic_id,v_teacher_id,'Common Irregular Verbs in Everyday Events','Notice and practise frequent irregular verbs in short personal contexts.','Objective: Use common irregular past forms for familiar completed events.
Content: Some frequent verbs do not take -ed in the past. Learn common pairs such as go/went, have/had, see/saw, buy/bought, take/took, eat/ate, make/made, and come/came. Use the past form for the completed event; the form does not change with he, she, or they.
Examples:
- I went to the market yesterday.
- She had soup for lunch.
- They saw a new film last week.
Common errors and corrections:
- Do not add -ed to an irregular past form: went, not goed.
- Do not add present-tense -s to an irregular past verb: he went, not he goes yesterday.
Guided practice: Match each base verb to its past form, then use it in a sentence with a finished-time expression.
Summary: Common irregular verbs have special past forms that must be learned and used for all subjects.','GRAMMAR',2,'DRAFT') RETURNING id INTO v_lesson_id; END IF;
    INSERT INTO lesson_revisions(topic_revision_id,source_lesson_id,teacher_id,title,description,content,skill_type,order_index,xp_reward,is_placement_test) VALUES(v_topic_revision_id,v_lesson_id,v_teacher_id,'Common Irregular Verbs in Everyday Events','Notice and practise frequent irregular verbs in short personal contexts.','Objective: Use common irregular past forms for familiar completed events.
Content: Some frequent verbs do not take -ed in the past. Learn common pairs such as go/went, have/had, see/saw, buy/bought, take/took, eat/ate, make/made, and come/came. Use the past form for the completed event; the form does not change with he, she, or they.
Examples:
- I went to the market yesterday.
- She had soup for lunch.
- They saw a new film last week.
Common errors and corrections:
- Do not add -ed to an irregular past form: went, not goed.
- Do not add present-tense -s to an irregular past verb: he went, not he goes yesterday.
Guided practice: Match each base verb to its past form, then use it in a sentence with a finished-time expression.
Summary: Common irregular verbs have special past forms that must be learned and used for all subjects.','GRAMMAR',2,10,FALSE) RETURNING id INTO v_lesson_revision_id;
