    SELECT id INTO v_lesson_id FROM lessons WHERE topic_id=v_topic_id AND title='Past Simple Negatives and Questions with Did';
    IF v_lesson_id IS NULL THEN INSERT INTO lessons(topic_id,teacher_id,title,description,content,skill_type,order_index,status) VALUES(v_topic_id,v_teacher_id,'Past Simple Negatives and Questions with Did','Practise do-support in questions and negative sentences about completed events.','Objective: Form past simple negatives and yes/no or wh- questions with did and the base verb.
Content: Use did not (didn''t) plus the base verb for a negative: She didn''t call. Use did plus subject plus base verb for a yes/no question: Did you call? Use a wh-word before did: Where did they stay? The past meaning is carried by did, so the main verb stays in its base form.
Examples:
- I didn''t watch television last night.
- Did Mai visit her aunt?
- Where did you put the tickets?
Common errors and corrections:
- After did or didn''t, use the base verb: didn''t go, not didn''t went.
- In questions, put did before the subject: Did he arrive?
Guided practice: Underline did/didn''t, then check that the main verb is in its base form.
Summary: Use did/didn''t for past questions and negatives; keep the main verb in its base form.','GRAMMAR',3,'DRAFT') RETURNING id INTO v_lesson_id; END IF;
    INSERT INTO lesson_revisions(topic_revision_id,source_lesson_id,teacher_id,title,description,content,skill_type,order_index,xp_reward,is_placement_test) VALUES(v_topic_revision_id,v_lesson_id,v_teacher_id,'Past Simple Negatives and Questions with Did','Practise do-support in questions and negative sentences about completed events.','Objective: Form past simple negatives and yes/no or wh- questions with did and the base verb.
Content: Use did not (didn''t) plus the base verb for a negative: She didn''t call. Use did plus subject plus base verb for a yes/no question: Did you call? Use a wh-word before did: Where did they stay? The past meaning is carried by did, so the main verb stays in its base form.
Examples:
- I didn''t watch television last night.
- Did Mai visit her aunt?
- Where did you put the tickets?
Common errors and corrections:
- After did or didn''t, use the base verb: didn''t go, not didn''t went.
- In questions, put did before the subject: Did he arrive?
Guided practice: Underline did/didn''t, then check that the main verb is in its base form.
Summary: Use did/didn''t for past questions and negatives; keep the main verb in its base form.','GRAMMAR',3,10,FALSE) RETURNING id INTO v_lesson_revision_id;
