    SELECT id INTO v_lesson_id FROM lessons WHERE topic_id=v_topic_id AND title='Integrated Past Events and Questions';
    IF v_lesson_id IS NULL THEN INSERT INTO lessons(topic_id,teacher_id,title,description,content,skill_type,order_index,status) VALUES(v_topic_id,v_teacher_id,'Integrated Past Events and Questions','Select the correct past form and structure while following a sequence of completed events.','Objective: Combine regular and irregular past forms with affirmative, negative, and question structures in short narratives.
Content: In a short account, use past simple for each completed event. Choose regular or irregular past forms in affirmative sentences. For negatives and questions, use did or didn''t with the base verb. Finished-time expressions such as yesterday, last week, and two days ago help establish the time.
Examples:
- We took the early train, visited the old town, and returned before dark.
- Did you see the notice?
- They didn''t buy tickets online.
Common errors and corrections:
- Do not mix did with a past-form main verb: Did she see it?
- Keep the event sequence in past simple when all actions are completed.
Guided practice: Read a short event sequence, identify the finished-time context, and check each verb form.
Summary: Use past forms in affirmative events and did/didn''t plus the base verb in questions and negatives.','GRAMMAR',4,'DRAFT') RETURNING id INTO v_lesson_id; END IF;
    INSERT INTO lesson_revisions(topic_revision_id,source_lesson_id,teacher_id,title,description,content,skill_type,order_index,xp_reward,is_placement_test) VALUES(v_topic_revision_id,v_lesson_id,v_teacher_id,'Integrated Past Events and Questions','Select the correct past form and structure while following a sequence of completed events.','Objective: Combine regular and irregular past forms with affirmative, negative, and question structures in short narratives.
Content: In a short account, use past simple for each completed event. Choose regular or irregular past forms in affirmative sentences. For negatives and questions, use did or didn''t with the base verb. Finished-time expressions such as yesterday, last week, and two days ago help establish the time.
Examples:
- We took the early train, visited the old town, and returned before dark.
- Did you see the notice?
- They didn''t buy tickets online.
Common errors and corrections:
- Do not mix did with a past-form main verb: Did she see it?
- Keep the event sequence in past simple when all actions are completed.
Guided practice: Read a short event sequence, identify the finished-time context, and check each verb form.
Summary: Use past forms in affirmative events and did/didn''t plus the base verb in questions and negatives.','GRAMMAR',4,10,FALSE) RETURNING id INTO v_lesson_revision_id;
